using System.Text.Json;
using System.Text.Json.Nodes;

namespace Lapis.Projects;

/// <summary>Thrown when a project file cannot be read.</summary>
public sealed class ProjectFormatException(string message, Exception? innerException = null) : Exception(message, innerException);

/// <summary>
/// A game project: a folder with a <c>.lapis</c> file, an <c>Assets</c> folder (scenes, scripts, models)
/// and a <c>.lapis</c> cache folder.
/// </summary>
/// <remarks>
/// <code>
/// MyGame/
///   MyGame.lapis        project file (this class)
///   MyGame.csproj       generated by the editor, for code completion in VS Code
///   Assets/             scenes, scripts and other assets
///   Settings/           project settings
///   .lapis/             cache, regenerated when needed
/// </code>
/// </remarks>
public sealed class LapisProject
{
    /// <summary>Extension of project files, including the dot.</summary>
    public const string FileExtension = ".lapis";

    /// <summary>Value of the <c>format</c> field.</summary>
    public const string FormatName = "lapis.project";

    /// <summary>Current version of the project file format.</summary>
    public const int FormatVersion = 1;

    private LapisProject(string filePath, string name, string? startScene)
    {
        FilePath = Path.GetFullPath(filePath);
        Name = name;
        StartScene = startScene;
    }

    /// <summary>Full path of the <c>.lapis</c> file.</summary>
    public string FilePath { get; }

    /// <summary>Project name; also the name of the generated C# project.</summary>
    public string Name { get; }

    /// <summary>Scene opened when the game starts, relative to <see cref="Directory"/> (forward slashes).</summary>
    public string? StartScene { get; set; }

    /// <summary>The project folder.</summary>
    public string Directory => Path.GetDirectoryName(FilePath)!;

    /// <summary>Folder with scenes, scripts and other assets.</summary>
    public string AssetsDirectory => Path.Combine(Directory, "Assets");

    /// <summary>Folder with project settings.</summary>
    public string SettingsDirectory => Path.Combine(Directory, "Settings");

    /// <summary>Folder for generated files; safe to delete.</summary>
    public string CacheDirectory => Path.Combine(Directory, ".lapis");

    /// <summary>Full path of the start scene, or null when none is set.</summary>
    public string? StartScenePath => StartScene is null ? null : Path.GetFullPath(Path.Combine(Directory, StartScene));

    /// <summary>
    /// Opens a project from its <c>.lapis</c> file, or from a folder that contains exactly one such file.
    /// </summary>
    /// <exception cref="ProjectFormatException">No valid project file was found.</exception>
    public static LapisProject Open(string path)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(path);

        var filePath = path;
        if (System.IO.Directory.Exists(path))
        {
            var candidates = System.IO.Directory.GetFiles(path, "*" + FileExtension);
            filePath = candidates.Length switch
            {
                1 => candidates[0],
                0 => throw new ProjectFormatException($"No {FileExtension} project file in '{path}'."),
                _ => throw new ProjectFormatException($"More than one {FileExtension} file in '{path}'; open the one you want."),
            };
        }

        JsonObject root;
        try
        {
            root = JsonNode.Parse(File.ReadAllText(filePath)) as JsonObject
                ?? throw new ProjectFormatException("A project file must contain a JSON object.");
        }
        catch (Exception exception) when (exception is JsonException or IOException or UnauthorizedAccessException)
        {
            throw new ProjectFormatException($"Could not read '{filePath}': {exception.Message}", exception);
        }

        if ((string?)root["format"] != FormatName)
        {
            throw new ProjectFormatException($"'{filePath}' is not a Lapis project file.");
        }

        var name = (string?)root["name"] ?? Path.GetFileNameWithoutExtension(filePath);
        return new LapisProject(filePath, name, (string?)root["startScene"]);
    }

    /// <summary>
    /// Creates a new project folder with the standard layout and an empty start scene.
    /// </summary>
    /// <param name="directory">Folder to create; must not contain a project yet.</param>
    /// <param name="name">Project name; defaults to the folder name.</param>
    /// <exception cref="ArgumentException">The name contains characters that are not allowed in identifiers.</exception>
    /// <exception cref="InvalidOperationException">The folder already contains a project.</exception>
    public static LapisProject Create(string directory, string? name = null)
    {
        name ??= Path.GetFileName(Path.TrimEndingDirectorySeparator(Path.GetFullPath(directory)));
        if (string.IsNullOrWhiteSpace(name) || !name.All(c => char.IsLetterOrDigit(c) || c is '_' or '-' or '.'))
        {
            throw new ArgumentException($"'{name}' is not a valid project name; use letters, digits, '_', '-' or '.'.", nameof(name));
        }

        System.IO.Directory.CreateDirectory(directory);
        if (System.IO.Directory.GetFiles(directory, "*" + FileExtension).Length > 0)
        {
            throw new InvalidOperationException($"'{directory}' already contains a Lapis project.");
        }

        var project = new LapisProject(Path.Combine(directory, name + FileExtension), name, "Assets/Scenes/Main.lscene");
        System.IO.Directory.CreateDirectory(Path.Combine(project.AssetsDirectory, "Scenes"));
        System.IO.Directory.CreateDirectory(Path.Combine(project.AssetsDirectory, "Scripts"));
        System.IO.Directory.CreateDirectory(project.SettingsDirectory);
        File.WriteAllText(Path.Combine(directory, ".gitignore"), ".lapis/\nBuilds/\nbin/\nobj/\n*.csproj\n");
        project.Save();
        return project;
    }

    /// <summary>Writes the project file.</summary>
    public void Save()
    {
        var root = new JsonObject
        {
            ["format"] = FormatName,
            ["version"] = FormatVersion,
            ["name"] = Name,
            ["engineVersion"] = EngineInfo.Version.ToString(3),
            ["startScene"] = StartScene,
        };

        File.WriteAllText(FilePath, root.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) + Environment.NewLine);
    }

    /// <summary>Converts a full path inside the project to a project-relative path with forward slashes.</summary>
    public string ToProjectPath(string fullPath) => Path.GetRelativePath(Directory, fullPath).Replace('\\', '/');
}
